/**
 * Base products available in the /customize builder.
 *
 * `printArea` describes the usable print panel as percentages of the mockup
 * image box: `cx`/`cy` are the centre, `w`/`h` the size. The customiser
 * positions uploaded artwork inside that rectangle, so adjusting a garment
 * mockup only means adjusting these four numbers.
 *
 * Mockup files are generated by `npm run assets` into `public/mockups`.
 */

const SWATCHES = {
  black: { name: 'Black', hex: '#151515' },
  white: { name: 'White', hex: '#f2efe9' },
  sand: { name: 'Sand', hex: '#d9cdba' },
  navy: { name: 'Navy', hex: '#1e2735' },
  olive: { name: 'Olive', hex: '#414736' },
  charcoal: { name: 'Charcoal', hex: '#33383d' },
  bone: { name: 'Bone', hex: '#e6e0d4' },
};

function colors(key, keys) {
  return keys.map((colorKey) => ({
    key: colorKey,
    ...SWATCHES[colorKey],
    image: `/mockups/${key}-${colorKey}.svg`,
  }));
}

