export const ACCEPTED_FILE_TYPES = ['image/png', 'image/jpeg', 'image/jpg', 'image/svg+xml'];
export const ACCEPTED_EXTENSIONS = '.png,.jpg,.jpeg,.svg';

/**
 * Upload ceiling. The preview keeps the file in the browser as a data URL and
 * the cart persists to localStorage, which is capped at a few megabytes — so a
 * large file would silently fail to persist. Keep this conservative.
 */
export const MAX_FILE_BYTES = 4 * 1024 * 1024;

export function getCustomProduct(key) {
  return CUSTOM_PRODUCTS.find((product) => product.key === key) || CUSTOM_PRODUCTS[0];
}
